OUTPUT_TOKENS = 1024
FRAMING_RESERVE = 64
MAX_INPUT_TOKENS = CONTEXT - OUTPUT_TOKENS - FRAMING_RESERVE
MODEL_BYTES = 2740937888
MODEL_SHA256 = "00fe7986ff5f6b463e62455821146049db6f9313603938a70800d1fb69ef11a4"
BASELINE_REQUEST_SHA256 = "6722efbaba019a1b5a66fe191943c6b58756a593c65a0a220cf2e15337d36dd9"
CANDIDATE_REQUEST_SHA256 = "820da9c4b166bb4808290a8e3d139f2253c171dccdbe4c1a42892a8823a1cbfb"
