def digest_bytes(data):
    return hashlib.sha256(data).hexdigest()


def digest_file(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(4 * 1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def read_request(path):
    raw = path.read_bytes()
    if len(raw) > 2 * 1024 * 1024:
        raise ValueError(f"request exceeds 2 MiB: {path}")
    if digest_bytes(raw) not in (BASELINE_REQUEST_SHA256, CANDIDATE_REQUEST_SHA256):
        raise ValueError(f"request is not one of the frozen diagnostic bodies: {path}")
    request = json.loads(raw)
    if not isinstance(request, dict) or request.get("model") != "native-form-planner-v2" or request.get("max_tokens") != OUTPUT_TOKENS:
        raise ValueError(f"request has unexpected model alias/output budget: {path}")
    if request.get("tool_choice") != "required" or request.get("parallel_tool_calls") is not False or "response_format" in request:
        raise ValueError(f"request is not a strict native-function request: {path}")
    messages = request.get("messages")
    if not isinstance(messages, list) or len(messages) not in (4, 6):
        raise ValueError(f"request is not a 4-role baseline or 6-role answer-error conversation: {path}")
    system, user, assistant, tool = messages[:4]
    if (not isinstance(system, dict) or set(system) != {"role", "content"} or system.get("role") != "system"
            or not isinstance(user, dict) or set(user) != {"role", "content"} or user.get("role") != "user"
            or not isinstance(user.get("content"), str)
            or not isinstance(assistant, dict) or assistant.get("role") != "assistant"
            or assistant.get("content") is not None or set(assistant) != {"role", "content", "tool_calls"}
            or not isinstance(tool, dict) or tool.get("role") != "tool"
            or set(tool) != {"role", "tool_call_id", "name", "content"}):
        raise ValueError(f"request has unexpected initial message objects or order: {path}")
    calls = assistant.get("tool_calls")
    if (not isinstance(calls, list) or len(calls) != 1 or not isinstance(calls[0], dict)
            or set(calls[0]) != {"id", "type", "function"} or calls[0].get("type") != "function"
            or calls[0].get("id") != tool.get("tool_call_id")
            or not isinstance(calls[0].get("id"), str) or not calls[0]["id"]
            or calls[0].get("function") != {"name": "captureNativeBrowser", "arguments": {}}
            or tool.get("name") != "captureNativeBrowser" or not isinstance(tool.get("content"), str)):
        raise ValueError(f"request capture tool event/result mismatch: {path}")
    try:
        context = json.loads(tool["content"], object_pairs_hook=unique_object)
    except (TypeError, json.JSONDecodeError, ValueError) as error:
        raise ValueError(f"request native capture result is not unique-key JSON: {path}") from error
    if not isinstance(context, dict) or "goal" in context:
        raise ValueError(f"request native capture result has invalid context fields: {path}")
    if len(messages) == 6:
        answer, error_result = messages[4:]
        if (not isinstance(answer, dict) or set(answer) != {"role", "content", "tool_calls"}
                or answer.get("role") != "assistant" or answer.get("content") is not None
                or not isinstance(answer.get("tool_calls"), list) or len(answer["tool_calls"]) != 1):
            raise ValueError(f"request prior answer is not one native assistant call: {path}")
        answer_call = answer["tool_calls"][0]
        if (not isinstance(answer_call, dict) or set(answer_call) != {"id", "type", "function"}
                or answer_call.get("type") != "function" or not isinstance(answer_call.get("id"), str)
                or not answer_call["id"] or not isinstance(answer_call.get("function"), dict)
                or set(answer_call["function"]) != {"name", "arguments"}
                or answer_call["function"].get("name") != "answer"
                or not isinstance(answer_call["function"].get("arguments"), str)):
            raise ValueError(f"request prior assistant call is not a native answer call: {path}")
        if (not isinstance(error_result, dict) or set(error_result) != {"role", "tool_call_id", "name", "content"}
                or error_result.get("role") != "tool" or error_result.get("name") != "answer"
                or error_result.get("tool_call_id") != answer_call.get("id")
                or not isinstance(error_result.get("content"), str)):
            raise ValueError(f"request answer error result is not linked to the prior call: {path}")
        try:
            answer_arguments = json.loads(answer_call["function"]["arguments"], object_pairs_hook=unique_object)
            error_payload = json.loads(error_result["content"], object_pairs_hook=unique_object)
        except (json.JSONDecodeError, ValueError) as error:
            raise ValueError(f"request answer call or error result is not unique-key JSON: {path}") from error
        if not isinstance(answer_arguments, dict) or set(answer_arguments) != {"text", "evidence"}:
            raise ValueError(f"request prior answer arguments do not match the answer schema: {path}")
        if (not isinstance(error_payload, dict) or set(error_payload) != {"error", "validationFeedback"}
                or error_payload.get("error") != "unsupportedAnswerClaim"
                or not isinstance(error_payload.get("validationFeedback"), str)):
            raise ValueError(f"request linked tool result is not an unsupported-answer validation error: {path}")
        if "rejectedProposal" in context or "validationFeedback" in context:
            raise ValueError(f"request candidate retained inline correction fields: {path}")
    elif "rejectedProposal" not in context or "validationFeedback" not in context:
        raise ValueError(f"request baseline lacks the captured inline correction fields: {path}")
    return raw, request


def write_json(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def named_workers():
    text = subprocess.check_output(["/bin/ps", "-axo", "pid=,comm="], text=True, timeout=3)
    return [int(fields[0]) for line in text.splitlines()
            if len(fields := line.strip().split(None, 1)) == 2
            and Path(fields[1]).name in ("llama-server", "llama-cli")]


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON argument key")
        result[key] = value
    return result


def matched_tool_result_context(request):
    """Return the synthetic capture result after validating its call ID pairing."""
    messages = request["messages"]
    assistant, tool = messages[2], messages[3]
    call = assistant["tool_calls"][0]
    if call["id"] != tool["tool_call_id"] or call["function"] != {"name": "captureNativeBrowser", "arguments": {}}:
        raise ValueError("captureNativeBrowser call ID or function does not match its tool result")
    context = json.loads(tool["content"])
    if not isinstance(context, dict) or "goal" in context:
        raise ValueError("matched capture context is invalid")
    return context


def parse_native_call(response, request):
    if not isinstance(response, dict) or response.get("model") != request.get("model"):
        raise ValueError("response model does not match request")
    if response.get("error") is not None:
        raise ValueError("completion response contains an error")
    choices = response.get("choices")
    if not isinstance(choices, list) or len(choices) != 1:
        raise ValueError("expected one model choice")
    choice = choices[0]
    if not isinstance(choice, dict) or choice.get("finish_reason") not in ("stop", "tool_calls"):
        raise ValueError("completion did not finish with a native tool call")
    message = choice.get("message")
    if not isinstance(message, dict) or message.get("role") != "assistant":
        raise ValueError("unexpected message role")
    if message.get("refusal") not in (None, ""):
        raise ValueError("model refused the operation")
    if message.get("function_call") is not None:
        raise ValueError("legacy function_call response is unsupported")
    content = message.get("content")
    if content is not None and (not isinstance(content, str) or len(content.encode("utf-8")) > 8192):
        raise ValueError("invalid ancillary assistant content")
    calls = message.get("tool_calls")
    if not isinstance(calls, list) or len(calls) != 1:
        raise ValueError("expected exactly one native call")
    call = calls[0]
    if (not isinstance(call, dict) or set(call) != {"type", "id", "function"}
            or call.get("type") != "function" or not isinstance(call.get("id"), str)
            or not 1 <= len(call["id"]) <= 128):
        raise ValueError("invalid native call")
    function = call.get("function")
    if not isinstance(function, dict) or set(function) != {"name", "arguments"}:
        raise ValueError("invalid function object")
    name, raw = function["name"], function["arguments"]
    tools = {tool["function"]["name"]: tool["function"] for tool in request["tools"]}
    if name not in tools or not isinstance(raw, str) or len(raw.encode("utf-8")) > 8192:
        raise ValueError("unknown function or oversized arguments")
    args = json.loads(raw, object_pairs_hook=unique_object)
    schema = tools[name]["parameters"]
    props = schema["properties"]
    if not isinstance(args, dict) or set(args) != set(schema["required"]) or not set(args) <= set(props):
        raise ValueError("wrong function argument fields")
    for key, value in args.items():
        spec = props[key]
        if not isinstance(value, str) or len(value.encode("utf-8")) > 1024 or not value.strip():
            raise ValueError("invalid string argument")
        if "enum" in spec and value not in spec["enum"]:
            raise ValueError("unobserved reference")
    user = matched_tool_result_context(request)
    contract = user.get("goalContract")
    requirements = contract.get("requirements") if isinstance(contract, dict) else None
    if not isinstance(requirements, list) or not 1 <= len(requirements) <= 8:
        raise ValueError("invalid retained requirement contract")
    ids = [item.get("id") for item in requirements if isinstance(item, dict)]
    if len(ids) != len(requirements) or any(not isinstance(item, str) or not item for item in ids) or len(set(ids)) != len(ids):
        raise ValueError("invalid retained requirement IDs")
    ref = args.get("reference", "")
    text = args.get("text", "")
    kind = name
    envelope = {"kind": kind, "reference": ref, "text": text,
        "requirements": {req_id: {"state": "pending", "evidence": []} for req_id in ids}}
    return {"name": name, "arguments": args}, envelope, content


def sanitized_response_review(response):
    """Persist native call names/arguments and structured JSON only, never prose or hidden reasoning."""
    if not isinstance(response, dict):
        return {"responseType": type(response).__name__}
    review = {}
    if isinstance(response.get("model"), str):
        review["model"] = response["model"]
    review["responseErrorPresent"] = response.get("error") is not None
    for key in ("usage", "timings"):
        if isinstance(response.get(key), dict):
            review[key] = response[key]
    choices = response.get("choices")
    if isinstance(choices, list):
        review["choices"] = []
        for choice in choices[:2]:
            if not isinstance(choice, dict):
                review["choices"].append({"choiceType": type(choice).__name__}); continue
            item = {"finish_reason": choice.get("finish_reason")}
            message = choice.get("message")
            if isinstance(message, dict):
                projection = {}
                if isinstance(message.get("role"), str):
                    projection["role"] = message["role"]
                content = message.get("content")
                if isinstance(content, str):
                    try:
                        parsed = json.loads(content)
                    except json.JSONDecodeError:
                        projection["contentUTF8Bytes"] = len(content.encode("utf-8"))
                    else:
                        if isinstance(parsed, (dict, list)):
                            projection["structuredContent"] = parsed
                        else:
                            projection["contentUTF8Bytes"] = len(content.encode("utf-8"))
                elif content is not None:
                    projection["contentType"] = type(content).__name__
                calls = message.get("tool_calls")
                if isinstance(calls, list):
                    projection["toolCalls"] = []
                    for call in calls[:4]:
                        function = call.get("function") if isinstance(call, dict) else None
                        if isinstance(function, dict):
                            projection["toolCalls"].append({
                                "name": function.get("name") if isinstance(function.get("name"), str) else None,
                                "arguments": function.get("arguments")})
                        else:
                            projection["toolCalls"].append({"callType": type(call).__name__})
                if message.get("refusal") is not None:
                    projection["refusalPresent"] = True
                if message.get("function_call") is not None:
                    projection["legacyFunctionCallPresent"] = True
                item["message"] = projection
            else:
                item["messageType"] = type(message).__name__
            review["choices"].append(item)
    return review


def run_worker(args, output, entries, report):
    if sys.platform != "darwin":
        raise ValueError("worker guard requires macOS proc_pid_rusage")
    if not args.runtime or not args.model:
        raise ValueError("--run requires --runtime and --model")
    binary, model = args.runtime.resolve(), args.model.resolve()
    if model.stat().st_size != MODEL_BYTES or digest_file(model) != MODEL_SHA256:
        raise ValueError("model does not match the pinned Qwen3.5-4B Q4_K_M bytes")
    if named_workers():
        raise RuntimeError("another llama worker is active")
    subprocess.run(["/usr/bin/codesign", "--verify", "--strict", str(binary)], check=True, timeout=5,
                   stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    version = subprocess.run([str(binary), "--version"], capture_output=True, text=True, timeout=5, check=True)
    version_text = version.stdout + version.stderr
    if "b9992" not in version_text and "6eddde06" not in version_text:
        raise ValueError("runtime version is not pinned b9992 / 6eddde06")
    report.update(runtimeSHA256=digest_file(binary), runtimeVersion=version_text.strip(), modelSHA256=MODEL_SHA256,
                  modelBytes=MODEL_BYTES, templateSource="Qwen model embedded template via /apply-template; no external template supplied")

    libproc = ctypes.CDLL("/usr/lib/libproc.dylib")
    libproc.proc_pid_rusage.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
    libproc.proc_pid_rusage.restype = ctypes.c_int
    def memory(pid):
        buffer = ctypes.create_string_buffer(1024)
        if libproc.proc_pid_rusage(pid, 4, ctypes.byref(buffer)) != 0:
            return None
        return max(struct.unpack_from("=QQ", buffer.raw, 64))
    if not memory(os.getpid()):
        raise RuntimeError("memory accounting unavailable")

    token = secrets.token_urlsafe(32)
    key = output / "temporary-api-key"
    with os.fdopen(os.open(key, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as handle:
        handle.write(token)
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0)); port = sock.getsockname()[1]
    launch = [str(binary), "--model", str(model), "--alias", "native-form-planner-v2",
        "--host", "127.0.0.1", "--port", str(port), "--api-key-file", str(key),
        "--offline", "--no-ui", "--no-mmproj", "--log-disable", "--parallel", "1",
        "--ctx-size", "6144", "--cache-ram", "0", "--threads", "4", "--threads-batch", "4",
        "--poll", "0", "--poll-batch", "0", "--n-gpu-layers", "99", "--jinja",
        "--reasoning", "on", "--reasoning-budget", "512"]
    report["workerThreads"] = 4
    report["launchProfile"] = "Production native-text launch args; one worker; 6144 context; 4 threads; 4 GiB process cap; request output 1024; one shared 45-second request deadline."
    write_json(output / "launch-arguments.json", launch)

    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *unused, **kwargs): return None
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())
    def fetch(path, body=None, timeout=5, authorized=True):
        headers = {"Content-Type": "application/json"}
        if authorized:
            headers["Authorization"] = "Bearer " + token
        data = None if body is None else body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        req = urllib.request.Request(f"http://127.0.0.1:{port}{path}", data=data, headers=headers)
        with opener.open(req, timeout=timeout) as response:
            data = response.read(2 * 1024 * 1024 + 1)
            if len(data) > 2 * 1024 * 1024:
                raise ValueError("loopback response exceeds 2 MiB")
            return json.loads(data)

    process = watcher = None
    done = threading.Event()
    started = time.monotonic()
    limits = {"startup": started + 45, "requests": None}
    samples = {"n": 0, "peak": 0, "workers": 0, "reason": None}
    lock = threading.Lock()
    def stop_owned():
        if process is not None and process.poll() is None:
            try: os.killpg(process.pid, signal.SIGTERM)
            except ProcessLookupError: pass
    def monitor():
        missed = 0
        last_workers = 0.0
        while not done.wait(0.1):
            if process.poll() is not None: return
            now = time.monotonic()
            measured = memory(process.pid)
            missed = missed + 1 if measured is None else 0
            if measured is not None:
                samples["n"] += 1; samples["peak"] = max(samples["peak"], measured)
            reason = "memory-limit" if measured is not None and measured > 4 * GIB else None
            if missed >= 10: reason = "memory-accounting-unavailable"
            with lock:
                if now > limits["startup"] and limits["requests"] is None: reason = "startup-deadline"
                if limits["requests"] is not None and now > limits["requests"]: reason = "shared-request-deadline"
            if now - started > 100: reason = "total-deadline"
            if now - last_workers >= 1:
                try:
                    workers = named_workers(); samples["workers"] = max(samples["workers"], len(workers))
                    if workers != [process.pid]: reason = "worker-count"
                except Exception: reason = "worker-count-unavailable"
                last_workers = now
            if reason:
                samples["reason"] = reason; stop_owned()
                if not done.wait(1) and process.poll() is None:
                    try: os.killpg(process.pid, signal.SIGKILL)
                    except ProcessLookupError: pass
                return

    try:
        with (output / "server.log").open("wb") as log:
            process = subprocess.Popen(launch, stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT,
                start_new_session=True, env={k:v for k,v in os.environ.items()
                    if not k.startswith(("LLAMA_", "GGML_", "HF_", "HUGGINGFACE_"))})
            report["ownedPID"] = process.pid
            watcher = threading.Thread(target=monitor, daemon=True); watcher.start()
            while True:
                if process.poll() is not None or samples["reason"]:
                    raise RuntimeError("owned worker stopped during startup")
                if time.monotonic() > limits["startup"]: raise TimeoutError("startup exceeded 45 seconds")
                try:
                    if fetch("/health", timeout=1).get("status") == "ok": break
                except (urllib.error.URLError, TimeoutError): pass
                time.sleep(0.1)
            try:
                fetch("/v1/chat/completions", body={}, authorized=False)
                raise RuntimeError("inference endpoint accepted unauthenticated request")
            except urllib.error.HTTPError as error:
                if error.code != 401: raise
            report["unauthenticatedRequestRejected"] = True

            # Bind every request to the actual embedded template and check all
            # token budgets before issuing any completion request.
            prepared = []
            for entry in entries:
                applied = fetch("/apply-template", entry["raw"])
                prompt = applied.get("prompt")
                if not isinstance(prompt, str) or not prompt:
                    raise ValueError("/apply-template did not return a prompt")
                tokens = fetch("/tokenize", {"model": entry["request"]["model"], "content": prompt,
                    "add_special": False, "parse_special": True}).get("tokens")
                if (not isinstance(tokens, list) or not tokens or len(tokens) > 8192
                        or any(type(token_id) is not int or token_id < 0 for token_id in tokens)):
                    raise ValueError("/tokenize returned malformed or overlong token IDs")
                prepared.append((entry, prompt, len(tokens)))
            over = [{"id": entry["id"], "tokens": count} for entry, _, count in prepared if count > MAX_INPUT_TOKENS]
            report["preflight"] = [{"id": entry["id"], "inputTokens": count,
                "promptSHA256": digest_bytes(prompt.encode("utf-8")), "fits": count <= MAX_INPUT_TOKENS}
                for entry, prompt, count in prepared]
            if over:
                report["status"] = "rejected-context-before-completions"
                report["overBudget"] = over
                return
            if args.tokenize_only:
                report["status"] = "tokenization-only"
                return
            with lock: limits["requests"] = time.monotonic() + 45
            for entry, prompt, count in prepared:
                began = time.monotonic()
                response = fetch("/v1/chat/completions", entry["raw"], timeout=45)
                elapsed = time.monotonic() - began
                review = sanitized_response_review(response)
                sidecar = output / (entry["id"] + "-visible-response-review.json")
                write_json(sidecar, review)
                choice = review.get("choices", [{}])[0] if review.get("choices") else {}
                finish_reason = choice.get("finish_reason") if isinstance(choice, dict) else None
                review_row = {"id": entry["id"], "finishReason": finish_reason,
                    "responseSidecar": sidecar.name, "responseModel": review.get("model")}
                report.setdefault("responseReviews", []).append(review_row)
                write_json(output / "result.json", report)
                report["completions"].append({"id": entry["id"], "inputTokens": count, "seconds": elapsed,
                    "finishReason": finish_reason, "responseSidecar": sidecar.name,
                    "usage": response.get("usage"), "timings": response.get("timings"),
                    "semanticAcceptance": "pending-root-review", "effectsDispatched": False})
                write_json(output / "result.json", report)
            report["status"] = "responses-collected-unqualified"
    finally:
        done.set()
        if watcher is not None: watcher.join(timeout=4)
        stop_owned()
        if process is not None:
            try: process.wait(timeout=3)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL); process.wait(timeout=3)
            report["ownedProcessExited"] = process.poll() is not None
            report["exitCode"] = process.returncode
        done.set()
        if watcher is not None: watcher.join(timeout=4)
        key.unlink(missing_ok=True)
        report["credentialRemoved"] = not key.exists()
        report["workerWallSeconds"] = time.monotonic() - started
        report["workerMemorySamples"] = samples["n"]
        report["peakSampledProcessMemoryBytes"] = samples["peak"]
        report["peakNamedWorkerCount"] = samples["workers"]
        if samples["reason"]: report["watchdogReason"] = samples["reason"]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--requests", nargs="+", type=Path, required=True,
                        help="one or more exact request-body JSON files")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--run", action="store_true", help="start one pinned local worker; otherwise prepare only")
    parser.add_argument("--tokenize-only", action="store_true", help="with --run, stop after all embedded-template token checks")
    parser.add_argument("--runtime", type=Path, default=RUNTIME_DEFAULT)
    parser.add_argument("--model", type=Path, help="pinned Qwen model file; required with --run")
    args = parser.parse_args()
    if args.tokenize_only and not args.run:
        parser.error("--tokenize-only requires --run to access the model's embedded template")
    if len(args.requests) > 2:
        parser.error("at most two requests are allowed per worker run")
    output = args.output.resolve(); output.mkdir(parents=True, exist_ok=False)
    entries = []
    for index, origin in enumerate(args.requests, 1):
        path = origin.resolve(); raw, request = read_request(path)
        entry_id = f"request-{index:02d}"
        target = output / (entry_id + "-request.json")
        target.write_bytes(raw)
        entries.append({"id": entry_id, "path": str(path), "request": request, "raw": raw,
                        "rawSHA256": digest_bytes(raw), "copy": str(target)})
    report = {"status": "prepared", "scope": "off-source native function-interface replay; no browser, MCP calls, or effects",
        "plannedCount": len(entries), "requests": [{"id": e["id"], "path": e["path"],
        "bodyCopy": e["copy"], "bodyBytes": len(e["raw"]), "bodySHA256": e["rawSHA256"]} for e in entries],
        "contextTokens": CONTEXT, "outputTokens": OUTPUT_TOKENS, "framingReserve": FRAMING_RESERVE,
        "maximumInputTokens": MAX_INPUT_TOKENS, "memoryStopLimitBytes": 4*GIB, "sharedCompletionDeadlineSeconds": 45,
        "modelSHA256": MODEL_SHA256, "modelBytes": MODEL_BYTES, "runnerSHA256": digest_file(Path(__file__)),
        "workerThreads": 4, "comparisonLimitations": ["Diagnostic outputs persist native function names/raw arguments and parsed JSON object/array content only; other assistant content is reduced to UTF-8 byte count, and semantic acceptance remains pending root review.", "No host adapter or browser effects are executed."],
        "responsePolicy": "Native function names/raw arguments and parsed JSON object/array content only; other assistant content is reduced to UTF-8 byte count; hidden reasoning and narrative are not persisted.",
        "productionChanged": False,
        "modelAliasChanged": False, "oracleSupplied": False, "interfaceComparison": "whole-page native-function outputs captured for root review; no semantic validator or effects", "completions": []}
    write_json(output / "result.json", report)
    if args.run:
        try:
            run_worker(args, output, entries, report)
        except BaseException as error:
            report["status"] = "failed"
            report["error"] = type(error).__name__ + ": " + str(error)
    else:
        report["status"] = "prepared-no-worker"
    write_json(output / "result.json", report)
    print(json.dumps({"status": report["status"], "requestCount": len(entries),
        "requestHashes": [e["rawSHA256"] for e in entries], "preflight": report.get("preflight", []),
        "completions": report.get("completions", []), "watchdogReason": report.get("watchdogReason")},
        ensure_ascii=False, indent=2))
    return 0 if report["status"] in ("prepared-no-worker", "tokenization-only", "responses-collected-unqualified", "rejected-context-before-completions") else 1

if __name__ == "__main__":
    raise SystemExit(main())
